import { useEffect, useState } from "react";
import { Animated, Easing, Pressable, StyleSheet, Text } from "react-native";
import type { PressableProps, StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface SwitchProps extends Omit<PressableProps, "style" | "children" | "onPress"> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  label?: string;
  /** Style of the outer pressable. */
  style?: StyleProp<ViewStyle>;
  /** Extend the inner, named parts of the switch: track, thumb or label. The React Native counterpart of `classNames`. */
  styles?: {
    track?: StyleProp<ViewStyle>;
    thumb?: StyleProp<ViewStyle>;
    label?: StyleProp<TextStyle>;
  };
}

/** Track inner width (42 - 6 padding) minus the 18px thumb. */
const size = 18;
const travel = 18;

export function Switch({ checked, defaultChecked = false, onCheckedChange, label, disabled, style, styles: parts, ...props }: SwitchProps) {
  const tokens = useTokens();
  const [internal, setInternal] = useState(defaultChecked);
  const on = checked ?? internal;
  const [position] = useState(() => new Animated.Value(on ? 1 : 0));

  useEffect(() => {
    Animated.timing(position, { toValue: on ? 1 : 0, duration: 220, easing: Easing.out(Easing.cubic), useNativeDriver: false }).start();
  }, [on, position]);

  const trackColor = position.interpolate({ inputRange: [0, 1], outputRange: [tokens.controlTrack, tokens.controlOn] });
  const thumbColor = position.interpolate({ inputRange: [0, 1], outputRange: [tokens.controlThumb, tokens.controlThumbOn] });
  const x = position.interpolate({ inputRange: [0, 1], outputRange: [0, travel] });

  return (
    <Pressable
      {...props}
      accessibilityRole="switch"
      accessibilityLabel={props.accessibilityLabel ?? label}
      accessibilityState={{ checked: on, disabled: Boolean(disabled) }}
      disabled={disabled}
      onPress={() => {
        if (checked === undefined) setInternal(!on);
        onCheckedChange?.(!on);
      }}
      style={[local.root, { minHeight: metrics.controlHeight.md, opacity: disabled ? 0.5 : 1 }, style]}
    >
      <Animated.View style={[local.track, { backgroundColor: trackColor }, parts?.track]}>
        <Animated.View style={[local.thumb, { backgroundColor: thumbColor, transform: [{ translateX: x }] }, parts?.thumb]} />
      </Animated.View>
      {label ? <Text style={[local.label, { color: tokens.foreground }, parts?.label]}>{label}</Text> : null}
    </Pressable>
  );
}

const local = StyleSheet.create({
  root: { flexDirection: "row", alignItems: "center", gap: metrics.space[3], alignSelf: "flex-start" },
  track: { width: 42, height: 24, padding: 3, justifyContent: "center", borderRadius: metrics.radiusPill },
  thumb: {
    width: size,
    height: size,
    borderRadius: metrics.radiusPill,
    shadowColor: "#000",
    shadowOpacity: 0.18,
    shadowRadius: 2,
    shadowOffset: { width: 0, height: 1 },
    elevation: 2,
  },
  label: { fontSize: metrics.text.sm },
});

export default Switch;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
